describe('Authentication Error Message', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should display an error message for incorrect password', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('wrongpassword');
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('be.visible').and('contain', 'Incorrect password');
    });

    it('should not display an error message for correct password', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="password"]').type('correctpassword');
        cy.get('button[type="submit"]').click();
        cy.get('.error-message').should('not.exist');
    });
});
